#!/usr/bin/env node
// Builds dist/rse.js — every component on window.RSE, for pages with no build step.
//
//   node scripts/build-bundle.mjs          # write
//   node scripts/build-bundle.mjs --check  # exit 1 if dist/rse.js is not what the sources produce
//
// The bundle is a copy, not a compile: components are written in React.createElement form on
// purpose, so no JSX transform is needed and a component written with JSX tags is rejected.
// It is regenerated whole from the manifest every time, so it cannot drift or keep dead code.
// React itself is not inside: load React 18 UMD first (assets/vendor/ has it).

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const checkOnly = process.argv.includes('--check');
const OUT = 'dist/rse.js';
const read = (p) => readFileSync(join(ROOT, p), 'utf8');
const manifest = JSON.parse(read('rse.manifest.json'));
const pkg = JSON.parse(read('package.json'));

const hasJsx = (src) =>
  src.split('\n').some((l) => /^\s*(return\s*\(|<[A-Z])/.test(l) && /<[A-Za-z][\w.]*[\s/>]/.test(l));

// 'use client' must sit above the imports in the source (Next.js App Router); inside the bundle's
// IIFE it is meaningless and a bare `import` is a syntax error, so both go.
const toBundleForm = (src) =>
  src
    .replace(/^(['"])use client\1;?\r?\n/, '')
    .replace(/^import React from 'react';\n/, '')
    .replace(/^export (function|const) /gm, '$1 ')
    .trimEnd();

let failed = false;
const exported = [];
let body = '';
for (const c of manifest.components) {
  if (!existsSync(join(ROOT, c.sourcePath))) { console.error(`missing source ${c.sourcePath}`); failed = true; continue; }
  const src = read(c.sourcePath);
  if (hasJsx(src)) { console.error(`${c.sourcePath}: written with JSX — use React.createElement form.`); failed = true; continue; }
  const names = [...src.matchAll(/^export (?:function|const) ([A-Za-z_$][\w$]*)/gm)].map((m) => m[1]);
  exported.push(...names);
  body += `\n// ${c.sourcePath}\ntry { (() => {\n${toBundleForm(src)}\nObject.assign(scope, { ${names.join(', ')} });\n})(); } catch (e) { RSE.__errors.push({ path: ${JSON.stringify(c.sourcePath)}, error: String((e && e.message) || e) }); }\n`;
}
if (failed) process.exit(1);

const out = `/* GENERATED by scripts/build-bundle.mjs — do not edit. Run \`npm run sync\`.
   ${pkg.name}@${pkg.version} — every component on window.RSE. Load React 18 UMD first. */
(() => {
const RSE = (window.RSE = window.RSE || {});
RSE.__errors = RSE.__errors || [];
RSE.version = ${JSON.stringify(pkg.version)};
const scope = {};
${body}
Object.assign(RSE, { ${exported.map((n) => `${n}: scope.${n}`).join(', ')} });
})();
`;

const current = existsSync(join(ROOT, OUT)) ? read(OUT) : null;
if (current === out) { console.log(`bundle up to date (${manifest.components.length} components)`); process.exit(0); }
if (checkOnly) { console.log(`${OUT} is out of date — run \`npm run sync\``); process.exit(1); }
mkdirSync(join(ROOT, 'dist'), { recursive: true });
writeFileSync(join(ROOT, OUT), out);
console.log(`wrote ${OUT} (${manifest.components.length} components, ${exported.length} exports)`);
